mapper.select:
SELECT

FROM Order4Activity a left join Account ac on a.accountId = ac.id
                      left join GoodsSku sku on a.skuId = sku.id
WHERE 1 = 1

    AND a.id = #{id}


    AND a.orderTxNo LIKE CONCAT('%',#{orderTxNo}, '%')


    AND a.activityType = #{activityType}


    AND a.activityId = #{activityId}


    AND a.skuId = #{skuId}


    AND a.spuId = #{spuId}


    AND a.accountId = #{accountId}


    AND a.orderStatus = #{orderStatus}


    AND a.paymentNo LIKE CONCAT('%',#{paymentNo}, '%') 


    AND a.paymentStatus = #{paymentStatus}


    AND a.activityCurrentRound = #{activityCurrentRound}


    AND a.isLotteryDrawn = #{isLotteryDrawn}


    AND a.isWinning = #{isWinning}


    AND a.isClaimLottery = #{isClaimLottery}

order by a.createTime desc

SELECT count(distinct(a.accountId)) FROM Order4Activity a
WHERE a.isWinning = 1
  AND a.activityType = #{activityType}
